1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"sort"
11		"syscall"
12		"time"
13	)
14	
15	// 包裹状态。
16	const (
17		// statusInStation 表示包裹当前在某站点（已收件、已完成交接或回执失败回到出发站）。
18		statusInStation = "在站"
19		// statusDelivering 表示包裹已随某个配送批次出站，正在配送中。
20		statusDelivering = "配送中"
21		// statusSigned 表示包裹已签收（回执结果为签收）。
22		statusSigned = "已签收"
23		// statusFrozen 表示在站包裹因异常被冻结：站点不变，禁止交接、配送出站与整批退回。
24		statusFrozen = "异常冻结"
25		// statusInTransit 表示包裹已随某张运输单离开源站、尚未在目的站被接收：
26		// 归属站点暂记源站，禁止交接、退回、配送出站与冻结。
27		statusInTransit = "站间在途"
28	)
29	
30	// 回执结果。
31	const (
32		resultSigned = "签收"
33		resultFailed = "失败"
34	)
35	
36	// Event 是包裹轨迹中的一条记录，按提交顺序追加。
37	type Event struct {
38		Op         string    `json:"op"`                   // 收件 | 交接 | 退回 | 出站 | 回执 | 冻结 | 解除冻结 | 收回 | 续接 | 撤销回执 | 发运 | 接收
39		Station    string    `json:"station"`              // 与该操作有关的站点（退回时为退回目的站，即原交接源站；冻结/解除冻结为包裹所在站点；收回/续接/撤销回执为批次出发站；发运时为源站，接收时为目的站）
40		Time       time.Time `json:"time"`                 // 发生时间
41		Request    string    `json:"request,omitempty"`    // 交接/退回/回执/收回/续接/撤销/接收请求号（收件、出站、发运记录为空）
42		From       string    `json:"from,omitempty"`       // 退回源站（原交接目的站，仅退回记录有）或发运/接收源站（仅发运、接收记录有）
43		To         string    `json:"to,omitempty"`         // 发运/接收目的站（仅发运、接收记录有）
44		Shipment   string    `json:"shipment,omitempty"`   // 运输单号（仅发运、接收记录有）
45		Reason     string    `json:"reason,omitempty"`     // 退回原因（仅退回记录有）、回执失败原因（仅失败回执有）、冻结原因（仅冻结记录有）、中止原因（仅收回记录有）、续接原因（仅续接记录有）或撤销原因（仅撤销回执记录有）
46		RefRequest string    `json:"refRequest,omitempty"` // 被退回的原交接请求号（仅退回记录有）或被撤销的原回执请求号（仅撤销回执记录有）
47		Batch      string    `json:"batch,omitempty"`      // 配送批次号（仅出站、回执、收回、续接、撤销回执记录有；续接时为新批次号）
48		FromBatch  string    `json:"fromBatch,omitempty"`  // 续接原批次号（仅续接记录有）
49		Courier    string    `json:"courier,omitempty"`    // 配送员（仅出站、续接记录有；续接时为新配送员）
50		Result     string    `json:"result,omitempty"`     // 回执结果：签收 | 失败（仅回执记录有）
51		// Incident 为冻结/解除冻结记录的异常单号；解除冻结时另外用 Request 存解除请求号、Note 存处理说明。
52		Incident string `json:"incident,omitempty"`
53		Note     string `json:"note,omitempty"`
54	}
55	
56	// Parcel 是一件包裹的台账信息。
57	type Parcel struct {
58		ID         string    `json:"id"`
59		Station    string    `json:"station"`    // 当前归属站点
60		Status     string    `json:"status"`     // 当前状态
61		Registered time.Time `json:"registered"` // 收件时间
62		Trail      []Event   `json:"trail"`      // 完整轨迹，按提交顺序排列
63	}
64	
65	// HandoffResult 记录一次成功交接，用于请求号去重与结果重放。
66	type HandoffResult struct {
67		Request    string    `json:"request"`
68		From       string    `json:"from"`
69		To         string    `json:"to"`
70		Parcels    []string  `json:"parcels"` // 按首次提交时给出的顺序保存
71		Time       time.Time `json:"time"`
72		ReturnedBy string    `json:"returnedBy,omitempty"` // 已成功退回该交接的退回请求号（未退回为空）
73	}
74	
75	// ReturnResult 记录一次成功的整批退回，用于退回请求号去重与结果重放。
76	type ReturnResult struct {
77		Request string    `json:"request"` // 退回请求号
78		Handoff string    `json:"handoff"` // 被退回的原交接请求号
79		From    string    `json:"from"`    // 退回源站（原交接目的站）
80		To      string    `json:"to"`      // 退回目的站（原交接源站）
81		Reason  string    `json:"reason"`
82		Parcels []string  `json:"parcels"` // 原交接批次，按原交接保存的顺序
83		Time    time.Time `json:"time"`
84	}
85	
86	// ReceiptEntry 是批次内一件包裹的当前回执记录（被新回执取代的已撤销条目由
87	// 台账级 Receipts 结果表与撤销记录共同保留）。
88	type ReceiptEntry struct {
89		Request string    `json:"request"`          // 回执请求号
90		Result  string    `json:"result"`           // 签收 | 失败
91		Reason  string    `json:"reason,omitempty"` // 失败原因（仅失败回执有）
92		Time    time.Time `json:"time"`
93		// RevokedBy 为撤销该回执的撤销请求号（未撤销为空）；撤销后该条不再计入有效回执。
94		RevokedBy string `json:"revokedBy,omitempty"`
95	}
96	
97	// BatchResult 记录一次成功的配送批次出站，用于批次号去重、结果重放与批次查询。
98	// 成员按首次提交时给出的顺序保存，保存后不可修改；批次完成后批次号也不能复用。
99	type BatchResult struct {
100		Batch    string                   `json:"batch"`
101		Station  string                   `json:"station"`  // 出发站
102		Courier  string                   `json:"courier"`  // 配送员
103		Parcels  []string                 `json:"parcels"`  // 批次成员，按首次提交顺序
104		Time     time.Time                `json:"time"`     // 出站时间
105		Receipts map[string]*ReceiptEntry `json:"receipts"` // 逐件回执，按包裹编号索引（未回执的包裹不在其中）
106		// AbortedBy 为中止该批次的中止请求号（未中止为空）；中止永久生效，批次不得复用。
107		AbortedBy string `json:"abortedBy,omitempty"`
108		// TransferredBy 为把该批次关闭为“已转交”的续接请求号（未转交为空）；
109		// 转交永久生效，与中止互斥，批次不得复用。
110		TransferredBy string `json:"transferredBy,omitempty"`
111		// RelayedFrom 与 RelayRequest 仅对续接创建的新批次有效：分别记录来源批次号
112		// 与创建本批次的续接请求号（普通出站批次为空）。
113		RelayedFrom  string `json:"relayedFrom,omitempty"`
114		RelayRequest string `json:"relayRequest,omitempty"`
115	}
116	
117	// Effective 返回批次当前有效（未撤销）的回执数量。
118	func (b *BatchResult) Effective() int {
119		n := 0
120		for _, e := range b.Receipts {
121			if e != nil && e.RevokedBy == "" {
122				n++
123			}
124		}
125		return n
126	}
127	
128	// Done 报告批次是否已完成（全部成员均有未撤销的有效回执）。
129	func (b *BatchResult) Done() bool { return b.Effective() == len(b.Parcels) }
130	
131	// ReceiptResult 记录一次成功的逐件回执，用于回执请求号去重与结果重放。
132	// 回执结果永久保留：即使之后被撤销，回执请求号也不删除、不释放。
133	type ReceiptResult struct {
134		Request string    `json:"request"` // 回执请求号
135		Batch   string    `json:"batch"`   // 所属配送批次号
136		Parcel  string    `json:"parcel"`  // 包裹编号
137		Result  string    `json:"result"`  // 签收 | 失败
138		Reason  string    `json:"reason,omitempty"`
139		Time    time.Time `json:"time"`
140		// RevokedBy 为撤销该回执的撤销请求号（未撤销为空）；每条回执只能被撤销一次。
141		RevokedBy string `json:"revokedBy,omitempty"`
142	}
143	
144	// FreezeResult 记录一次成功的异常冻结，用于异常单号去重与结果重放。
145	// 异常单号标识一次异常，解除后也不能复用；失败的首次冻结不占用异常单号。
146	type FreezeResult struct {
147		Incident string    `json:"incident"` // 异常单号
148		Parcel   string    `json:"parcel"`   // 被冻结的包裹编号
149		Station  string    `json:"station"`  // 冻结时包裹所在站点（冻结与解除期间均不变）
150		Reason   string    `json:"reason"`   // 清理后的冻结原因
151		Time     time.Time `json:"time"`     // 冻结时间
152		// ReleasedBy 为解除该异常单的解除请求号（未解除为空）；解除后异常单永久保留、不得复用。
153		ReleasedBy string `json:"releasedBy,omitempty"`
154	}
155	
156	// UnfreezeResult 记录一次成功的解除冻结，用于解除请求号去重与结果重放。
157	// 解除请求号独立去重，可与异常单号、包裹号及其他业务编号同名；失败的首次解除不占用请求号。
158	type UnfreezeResult struct {
159		Request  string    `json:"request"`  // 解除请求号
160		Incident string    `json:"incident"` // 被解除的异常单号
161		Parcel   string    `json:"parcel"`   // 对应包裹编号
162		Note     string    `json:"note"`     // 清理后的处理说明
163		Time     time.Time `json:"time"`     // 解除时间
164	}
165	
166	// AbortResult 记录一次成功的配送批次中止，用于中止请求号去重与结果重放。
167	// 中止表示配送员已将该批次全部尚未回执的包裹实物收回出发站：批次永久关闭，
168	// 原成员顺序、配送员与出站时间保留不变，已回执成员及其回执完全保留。
169	// 中止请求号独立去重，可与批次号、包裹号及其他业务编号同名；失败的首次中止不占用请求号。
170	type AbortResult struct {
171		Request string    `json:"request"` // 中止请求号
172		Batch   string    `json:"batch"`   // 被中止的配送批次号
173		Station string    `json:"station"` // 出发站（收回目的站，取自原批次）
174		Reason  string    `json:"reason"`  // 清理后的中止原因
175		Parcels []string  `json:"parcels"` // 首次收回的未回执包裹，按原批次成员顺序
176		Time    time.Time `json:"time"`    // 中止时间
177	}
178	
179	// TransferResult 记录一次成功的配送途中整批续接，用于续接请求号去重与结果重放。
180	// 续接表示原配送员把原批次全部尚未回执的包裹在配送途中交给另一配送员：
181	// 新批次按原顺序接纳全部未回执件继续配送，包裹保持“配送中”及原站点，
182	// 原批次永久关闭为“已转交”。续接请求号独立去重，可与批次号、包裹号及其他
183	// 业务编号同名；失败的首次续接不占用请求号。
184	type TransferResult struct {
185		Request     string    `json:"request"`     // 续接请求号
186		FromBatch   string    `json:"fromBatch"`   // 原批次号
187		ToBatch     string    `json:"toBatch"`     // 新批次号
188		Station     string    `json:"station"`     // 出发站（沿用原批次）
189		FromCourier string    `json:"fromCourier"` // 原配送员（取自原批次）
190		ToCourier   string    `json:"toCourier"`   // 新配送员
191		Reason      string    `json:"reason"`      // 清理后的续接原因
192		Parcels     []string  `json:"parcels"`     // 首次转交集合（原批次未回执成员，按原成员顺序）
193		Time        time.Time `json:"time"`        // 接手时间
194	}
195	
196	// RevokeResult 记录一次成功的误录回执撤销，用于撤销请求号去重与结果重放。
197	// 撤销只更正台账：经核实包裹实际仍由原配送员配送，撤销错误的签收或失败登记，
198	// 不收回实物。原回执结果与轨迹永久保留并标记已撤销，回执请求号不删除也不释放。
199	// 撤销请求号独立去重，可与批次号、包裹号、回执请求号及其他业务编号同名；
200	// 失败的首次撤销不占用请求号。
201	type RevokeResult struct {
202		Request string    `json:"request"` // 撤销请求号
203		Receipt string    `json:"receipt"` // 被撤销的原回执请求号
204		Batch   string    `json:"batch"`   // 所属配送批次号（取自原回执，不可另选）
205		Parcel  string    `json:"parcel"`  // 包裹编号（取自原回执，不可另选）
206		Reason  string    `json:"reason"`  // 清理后的撤销原因
207		Time    time.Time `json:"time"`    // 撤销时间
208	}
209	
210	// ShipmentResult 记录一次成功的站间发运，用于运输单号去重、结果重放与运输单查询。
211	// 发运表示整单包裹已离开源站、尚未到达目的站：整单转为“站间在途”，归属站点暂记
212	// 源站，成员按首次提交顺序保存，保存后不可修改。运输单号独立于已有各类编号，
213	// 接收后也不释放；失败的首次发运不占用运输单号。
214	type ShipmentResult struct {
215		Shipment string    `json:"shipment"` // 运输单号
216		From     string    `json:"from"`     // 源站
217		To       string    `json:"to"`       // 目的站
218		Parcels  []string  `json:"parcels"`  // 成员，按首次提交顺序
219		Time     time.Time `json:"time"`     // 发运时间
220		// ReceivedBy 为接收该运输单的接收请求号（未接收为空）；接收永久生效，每单只能成功接收一次。
221		ReceivedBy string `json:"receivedBy,omitempty"`
222	}
223	
224	// ReceiveResult 记录一次成功的整单到站接收，用于接收请求号去重与结果重放。
225	// 接收表示运输单全部成员已到达目的站：按发运保存顺序全部改归目的站、恢复在站，
226	// 运输单永久标记为已接收。接收请求号与运输单号及已有各类编号分属独立去重范围，
227	// 允许同名；失败的首次接收不占用请求号。
228	type ReceiveResult struct {
229		Request  string    `json:"request"`  // 接收请求号
230		Shipment string    `json:"shipment"` // 被接收的运输单号
231		Station  string    `json:"station"`  // 接收站点（即运输单目的站）
232		Parcels  []string  `json:"parcels"`  // 全部成员，按发运保存顺序
233		Time     time.Time `json:"time"`     // 接收时间
234	}
235	
236	// ledgerFile 是本地数据文件的磁盘结构。
237	type ledgerFile struct {
238		Version   int                        `json:"version"`
239		Parcels   map[string]*Parcel         `json:"parcels"`
240		Handoffs  map[string]*HandoffResult  `json:"handoffs"`
241		Returns   map[string]*ReturnResult   `json:"returns"`
242		Batches   map[string]*BatchResult    `json:"batches"`
243		Receipts  map[string]*ReceiptResult  `json:"receipts"`
244		Freezes   map[string]*FreezeResult   `json:"freezes"`   // 以异常单号为键（含已解除的异常单，永久保留）
245		Unfreezes map[string]*UnfreezeResult `json:"unfreezes"` // 以解除请求号为键
246		Aborts    map[string]*AbortResult    `json:"aborts"`    // 以中止请求号为键
247		Transfers map[string]*TransferResult `json:"transfers"` // 以续接请求号为键
248		Revokes   map[string]*RevokeResult   `json:"revokes"`   // 以撤销请求号为键
249		Shipments map[string]*ShipmentResult `json:"shipments"` // 以运输单号为键（含已接收的运输单，永久保留）
250		Receives  map[string]*ReceiveResult  `json:"receives"`  // 以接收请求号为键
251	}
252	
253	// Store 是一个数据文件对应的包裹站点交接台账。
254	type Store struct {
255		path string
256		data ledgerFile
257	}
258	
259	var (
260		// ErrCorrupt 表示数据文件已存在但内容损坏，不得当作空库继续读写。
261		ErrCorrupt = errors.New("数据文件已损坏")
262		// ErrNotFound 表示包裹编号在台账中不存在。
263		ErrNotFound = errors.New("包裹不存在")
264	)
265	
266	// Open 打开（或在文件不存在时建立）一个本地台账。
267	// 文件不存在时仅初始化内存结构，真正建文件发生在首次成功保存时。
268	func Open(path string) (*Store, error) {
269		s := &Store{path: path}
270		raw, err := os.ReadFile(path)
271		if err != nil {
272			if os.IsNotExist(err) {
273				s.data = ledgerFile{Version: 1, Parcels: map[string]*Parcel{}, Handoffs: map[string]*HandoffResult{},
274					Returns: map[string]*ReturnResult{}, Batches: map[string]*BatchResult{}, Receipts: map[string]*ReceiptResult{},
275					Freezes: map[string]*FreezeResult{}, Unfreezes: map[string]*UnfreezeResult{}, Aborts: map[string]*AbortResult{},
276					Transfers: map[string]*TransferResult{}, Revokes: map[string]*RevokeResult{}, Shipments: map[string]*ShipmentResult{},
277					Receives: map[string]*ReceiveResult{}}
278				return s, nil
279			}
280			return nil, fmt.Errorf("读取数据文件失败: %w", err)
281		}
282		if len(bytes.TrimSpace(raw)) == 0 {
283			return nil, fmt.Errorf("%w: 文件为空", ErrCorrupt)
284		}
285		if err := json.Unmarshal(raw, &s.data); err != nil {
286			return nil, fmt.Errorf("%w: %v", ErrCorrupt, err)
287		}
288		if s.data.Version != 1 || s.data.Parcels == nil || s.data.Handoffs == nil {
289			return nil, fmt.Errorf("%w: 缺少必要字段或版本不受支持", ErrCorrupt)
290		}
291		// 早期版本的数据文件没有 returns/batches/receipts/freeze/abort/revoke 相关字段：按空表处理，无需手工修改。
292		if s.data.Returns == nil {
293			s.data.Returns = map[string]*ReturnResult{}
294		}
295		if s.data.Batches == nil {
296			s.data.Batches = map[string]*BatchResult{}
297		}
298		if s.data.Receipts == nil {
299			s.data.Receipts = map[string]*ReceiptResult{}
300		}
301		if s.data.Freezes == nil {
302			s.data.Freezes = map[string]*FreezeResult{}
303		}
304		if s.data.Unfreezes == nil {
305			s.data.Unfreezes = map[string]*UnfreezeResult{}
306		}
307		if s.data.Aborts == nil {
308			s.data.Aborts = map[string]*AbortResult{}
309		}
310		if s.data.Transfers == nil {
311			s.data.Transfers = map[string]*TransferResult{}
312		}
313		if s.data.Revokes == nil {
314			s.data.Revokes = map[string]*RevokeResult{}
315		}
316		// 早期版本的数据文件没有 shipments/receives 字段：按空表处理，无需手工修改。
317		if s.data.Shipments == nil {
318			s.data.Shipments = map[string]*ShipmentResult{}
319		}
320		if s.data.Receives == nil {
321			s.data.Receives = map[string]*ReceiveResult{}
322		}
323		for _, b := range s.data.Batches {
324			if b != nil && b.Receipts == nil {
325				b.Receipts = map[string]*ReceiptEntry{}
326			}
327		}
328		if err := s.data.validate(); err != nil {
329			return nil, err
330		}
331		return s, nil
332	}
333	
334	// validate 校验载入内容内部自洽，防止损坏数据被当作有效台账继续使用。
335	func (l *ledgerFile) validate() error {
336		for id, p := range l.Parcels {
337			if p == nil || id != p.ID || p.Station == "" || p.Status == "" || len(p.Trail) == 0 {
338				return fmt.Errorf("%w: 包裹 %q 记录不完整", ErrCorrupt, id)
339			}
340			switch p.Status {
341			case statusInStation, statusDelivering, statusSigned, statusFrozen, statusInTransit:
342			default:
343				return fmt.Errorf("%w: 包裹 %q 的状态 %q 不受支持", ErrCorrupt, id, p.Status)
344			}
345			for i, e := range p.Trail {
346				if e.Op == "" || e.Station == "" || e.Time.IsZero() {
347					return fmt.Errorf("%w: 包裹 %q 第 %d 条轨迹缺少操作、站点或发生时间", ErrCorrupt, id, i+1)
348				}
349				if e.Op == "退回" {
350					if e.Request == "" || e.Reason == "" || e.From == "" {
351						return fmt.Errorf("%w: 包裹 %q 第 %d 条退回轨迹缺少退回请求号、源站或原因", ErrCorrupt, id, i+1)
352					}
353					if _, ok := l.Handoffs[e.RefRequest]; !ok {
354						return fmt.Errorf("%w: 包裹 %q 第 %d 条退回轨迹引用了不存在的原交接 %q", ErrCorrupt, id, i+1, e.RefRequest)
355					}
356				}
357				if e.Op == "出站" {
358					if e.Batch == "" || e.Courier == "" {
359						return fmt.Errorf("%w: 包裹 %q 第 %d 条出站轨迹缺少批次号或配送员", ErrCorrupt, id, i+1)
360					}
361					if _, ok := l.Batches[e.Batch]; !ok {
362						return fmt.Errorf("%w: 包裹 %q 第 %d 条出站轨迹引用了不存在的批次 %q", ErrCorrupt, id, i+1, e.Batch)
363					}
364				}
365				if e.Op == "回执" {
366					if e.Batch == "" || e.Request == "" || (e.Result != resultSigned && e.Result != resultFailed) {
367						return fmt.Errorf("%w: 包裹 %q 第 %d 条回执轨迹缺少批次号、请求号或结果无效", ErrCorrupt, id, i+1)
368					}
369					if e.Result == resultFailed && e.Reason == "" {
370						return fmt.Errorf("%w: 包裹 %q 第 %d 条失败回执轨迹缺少原因", ErrCorrupt, id, i+1)
371					}
372					if _, ok := l.Batches[e.Batch]; !ok {
373						return fmt.Errorf("%w: 包裹 %q 第 %d 条回执轨迹引用了不存在的批次 %q", ErrCorrupt, id, i+1, e.Batch)
374					}
375				}
376				if e.Op == "撤销回执" {
377					if e.Batch == "" || e.Request == "" || e.RefRequest == "" || e.Reason == "" {
378						return fmt.Errorf("%w: 包裹 %q 第 %d 条撤销回执轨迹缺少批次号、撤销请求号、原回执请求号或原因", ErrCorrupt, id, i+1)
379					}
380					b, ok := l.Batches[e.Batch]
381					if !ok {
382						return fmt.Errorf("%w: 包裹 %q 第 %d 条撤销回执轨迹引用了不存在的批次 %q", ErrCorrupt, id, i+1, e.Batch)
383					}
384					if e.Station != b.Station {
385						return fmt.Errorf("%w: 包裹 %q 第 %d 条撤销回执轨迹的站点 %q 与批次 %q 出发站 %q 不一致",
386							ErrCorrupt, id, i+1, e.Station, e.Batch, b.Station)
387					}
388					rv, ok := l.Revokes[e.Request]
389					if !ok {
390						return fmt.Errorf("%w: 包裹 %q 第 %d 条撤销回执轨迹引用了不存在的撤销请求 %q", ErrCorrupt, id, i+1, e.Request)
391					}
392					if rv.Receipt != e.RefRequest || rv.Batch != e.Batch || rv.Parcel != id || rv.Reason != e.Reason || !rv.Time.Equal(e.Time) {
393						return fmt.Errorf("%w: 包裹 %q 第 %d 条撤销回执轨迹与撤销请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
394					}
395				}
396				if e.Op == "收回" {
397					if e.Batch == "" || e.Request == "" || e.Reason == "" {
398						return fmt.Errorf("%w: 包裹 %q 第 %d 条收回轨迹缺少批次号、中止请求号或原因", ErrCorrupt, id, i+1)
399					}
400					a, ok := l.Aborts[e.Request]
401					if !ok {
402						return fmt.Errorf("%w: 包裹 %q 第 %d 条收回轨迹引用了不存在的中止请求 %q", ErrCorrupt, id, i+1, e.Request)
403					}
404					if a.Batch != e.Batch || a.Station != e.Station || a.Reason != e.Reason || !a.Time.Equal(e.Time) {
405						return fmt.Errorf("%w: 包裹 %q 第 %d 条收回轨迹与中止请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
406					}
407					inAbort := false
408					for _, pid := range a.Parcels {
409						if pid == id {
410							inAbort = true
411							break
412						}
413					}
414					if !inAbort {
415						return fmt.Errorf("%w: 包裹 %q 第 %d 条收回轨迹不在中止请求 %q 的收回集合中", ErrCorrupt, id, i+1, e.Request)
416					}
417				}
418				if e.Op == "续接" {
419					if e.Batch == "" || e.FromBatch == "" || e.Courier == "" || e.Request == "" || e.Reason == "" {
420						return fmt.Errorf("%w: 包裹 %q 第 %d 条续接轨迹缺少新批次号、原批次号、新配送员、续接请求号或原因", ErrCorrupt, id, i+1)
421					}
422					t, ok := l.Transfers[e.Request]
423					if !ok {
424						return fmt.Errorf("%w: 包裹 %q 第 %d 条续接轨迹引用了不存在的续接请求 %q", ErrCorrupt, id, i+1, e.Request)
425					}
426					if t.FromBatch != e.FromBatch || t.ToBatch != e.Batch || t.ToCourier != e.Courier ||
427						t.Station != e.Station || t.Reason != e.Reason || !t.Time.Equal(e.Time) {
428						return fmt.Errorf("%w: 包裹 %q 第 %d 条续接轨迹与续接请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
429					}
430					inTransfer := false
431					for _, pid := range t.Parcels {
432						if pid == id {
433							inTransfer = true
434							break
435						}
436					}
437					if !inTransfer {
438						return fmt.Errorf("%w: 包裹 %q 第 %d 条续接轨迹不在续接请求 %q 的转交集合中", ErrCorrupt, id, i+1, e.Request)
439					}
440				}
441				if e.Op == "发运" {
442					if e.Shipment == "" || e.From == "" || e.To == "" {
443						return fmt.Errorf("%w: 包裹 %q 第 %d 条发运轨迹缺少运输单号、源站或目的站", ErrCorrupt, id, i+1)
444					}
445					sh, ok := l.Shipments[e.Shipment]
446					if !ok {
447						return fmt.Errorf("%w: 包裹 %q 第 %d 条发运轨迹引用了不存在的运输单 %q", ErrCorrupt, id, i+1, e.Shipment)
448					}
449					if sh.From != e.From || sh.To != e.To || e.Station != e.From || !sh.Time.Equal(e.Time) {
450						return fmt.Errorf("%w: 包裹 %q 第 %d 条发运轨迹与运输单 %q 记录不一致", ErrCorrupt, id, i+1, e.Shipment)
451					}
452					inShipment := false
453					for _, pid := range sh.Parcels {
454						if pid == id {
455							inShipment = true
456							break
457						}
458					}
459					if !inShipment {
460						return fmt.Errorf("%w: 包裹 %q 第 %d 条发运轨迹不在运输单 %q 的成员集合中", ErrCorrupt, id, i+1, e.Shipment)
461					}
462				}
463				if e.Op == "接收" {
464					if e.Shipment == "" || e.Request == "" || e.From == "" || e.To == "" {
465						return fmt.Errorf("%w: 包裹 %q 第 %d 条接收轨迹缺少运输单号、接收请求号、源站或目的站", ErrCorrupt, id, i+1)
466					}
467					rv, ok := l.Receives[e.Request]
468					if !ok {
469						return fmt.Errorf("%w: 包裹 %q 第 %d 条接收轨迹引用了不存在的接收请求 %q", ErrCorrupt, id, i+1, e.Request)
470					}
471					if rv.Shipment != e.Shipment || rv.Station != e.Station || e.Station != e.To || !rv.Time.Equal(e.Time) {
472						return fmt.Errorf("%w: 包裹 %q 第 %d 条接收轨迹与接收请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
473					}
474					inReceive := false
475					for _, pid := range rv.Parcels {
476						if pid == id {
477							inReceive = true
478							break
479						}
480					}
481					if !inReceive {
482						return fmt.Errorf("%w: 包裹 %q 第 %d 条接收轨迹不在接收请求 %q 的成员集合中", ErrCorrupt, id, i+1, e.Request)
483					}
484				}
485				if e.Op == "冻结" {
486					if e.Incident == "" || e.Reason == "" {
487						return fmt.Errorf("%w: 包裹 %q 第 %d 条冻结轨迹缺少异常单号或原因", ErrCorrupt, id, i+1)
488					}
489					f, ok := l.Freezes[e.Incident]
490					if !ok {
491						return fmt.Errorf("%w: 包裹 %q 第 %d 条冻结轨迹引用了不存在的异常单 %q", ErrCorrupt, id, i+1, e.Incident)
492					}
493					if f.Parcel != id || f.Reason != e.Reason || f.Station != e.Station || !f.Time.Equal(e.Time) {
494						return fmt.Errorf("%w: 包裹 %q 第 %d 条冻结轨迹与异常单 %q 记录不一致", ErrCorrupt, id, i+1, e.Incident)
495					}
496				}
497				if e.Op == "解除冻结" {
498					if e.Incident == "" || e.Request == "" || e.Note == "" {
499						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除冻结轨迹缺少异常单号、解除请求号或处理说明", ErrCorrupt, id, i+1)
500					}
501					f, ok := l.Freezes[e.Incident]
502					if !ok {
503						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除冻结轨迹引用了不存在的异常单 %q", ErrCorrupt, id, i+1, e.Incident)
504					}
505					if f.Parcel != id || f.Station != e.Station || f.ReleasedBy != e.Request {
506						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除冻结轨迹与异常单 %q 不匹配", ErrCorrupt, id, i+1, e.Incident)
507					}
508					u, ok := l.Unfreezes[e.Request]
509					if !ok || u.Incident != e.Incident || u.Parcel != id || u.Note != e.Note || !u.Time.Equal(e.Time) {
510						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除冻结轨迹与解除请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
511					}
512				}
513			}
514		}
515		for req, h := range l.Handoffs {
516			if h == nil || req != h.Request || h.From == "" || h.To == "" || len(h.Parcels) == 0 {
517				return fmt.Errorf("%w: 请求号 %q 的交接结果不完整", ErrCorrupt, req)
518			}
519			for _, id := range h.Parcels {
520				if _, ok := l.Parcels[id]; !ok {
521					return fmt.Errorf("%w: 请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, id)
522				}
523			}
524			if h.ReturnedBy != "" {
525				r, ok := l.Returns[h.ReturnedBy]
526				if !ok || r.Handoff != req {
527					return fmt.Errorf("%w: 交接 %q 标记的退回请求号 %q 无法对应", ErrCorrupt, req, h.ReturnedBy)
528				}
529			}
530		}
531		for req, r := range l.Returns {
532			if r == nil || req != r.Request || r.Handoff == "" || r.From == "" || r.To == "" ||
533				r.Reason == "" || len(r.Parcels) == 0 || r.Time.IsZero() {
534				return fmt.Errorf("%w: 退回请求号 %q 的退回结果不完整", ErrCorrupt, req)
535			}
536			h, ok := l.Handoffs[r.Handoff]
537			if !ok {
538				return fmt.Errorf("%w: 退回请求号 %q 引用了不存在的原交接 %q", ErrCorrupt, req, r.Handoff)
539			}
540			if h.ReturnedBy != req || r.From != h.To || r.To != h.From || !sameSet(r.Parcels, h.Parcels) {
541				return fmt.Errorf("%w: 退回请求号 %q 与原交接 %q 的记录不一致", ErrCorrupt, req, r.Handoff)
542			}
543			for _, id := range r.Parcels {
544				if _, ok := l.Parcels[id]; !ok {
545					return fmt.Errorf("%w: 退回请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, id)
546				}
547			}
548		}
549		for id, b := range l.Batches {
550			if b == nil || id != b.Batch || b.Station == "" || b.Courier == "" || len(b.Parcels) == 0 || b.Time.IsZero() {
551				return fmt.Errorf("%w: 批次号 %q 的出站结果不完整", ErrCorrupt, id)
552			}
553			seen := make(map[string]bool, len(b.Parcels))
554			for _, pid := range b.Parcels {
555				if seen[pid] {
556					return fmt.Errorf("%w: 批次 %q 的成员 %q 重复", ErrCorrupt, id, pid)
557				}
558				seen[pid] = true
559				if _, ok := l.Parcels[pid]; !ok {
560					return fmt.Errorf("%w: 批次 %q 引用了不存在的包裹 %q", ErrCorrupt, id, pid)
561				}
562			}
563			for pid, e := range b.Receipts {
564				if e == nil || !seen[pid] || e.Request == "" || e.Time.IsZero() ||
565					(e.Result != resultSigned && e.Result != resultFailed) ||
566					(e.Result == resultFailed && e.Reason == "") || (e.Result == resultSigned && e.Reason != "") {
567					return fmt.Errorf("%w: 批次 %q 中包裹 %q 的回执记录不完整", ErrCorrupt, id, pid)
568				}
569				rc, ok := l.Receipts[e.Request]
570				if !ok || rc.Batch != id || rc.Parcel != pid {
571					return fmt.Errorf("%w: 批次 %q 中包裹 %q 的回执请求号 %q 无法对应", ErrCorrupt, id, pid, e.Request)
572				}
573				if e.RevokedBy != rc.RevokedBy {
574					return fmt.Errorf("%w: 批次 %q 中包裹 %q 的回执条目与回执请求号 %q 的撤销标记不一致", ErrCorrupt, id, pid, e.Request)
575				}
576			}
577			if b.AbortedBy != "" {
578				a, ok := l.Aborts[b.AbortedBy]
579				if !ok || a.Batch != id {
580					return fmt.Errorf("%w: 批次 %q 标记的中止请求号 %q 无法对应", ErrCorrupt, id, b.AbortedBy)
581				}
582			}
583			if b.TransferredBy != "" {
584				if b.AbortedBy != "" {
585					return fmt.Errorf("%w: 批次 %q 不能同时标记中止与转交", ErrCorrupt, id)
586				}
587				t, ok := l.Transfers[b.TransferredBy]
588				if !ok || t.FromBatch != id {
589					return fmt.Errorf("%w: 批次 %q 标记的续接请求号 %q 无法对应", ErrCorrupt, id, b.TransferredBy)
590				}
591			}
592			if b.RelayedFrom != "" {
593				t, ok := l.Transfers[b.RelayRequest]
594				if !ok || t.ToBatch != id || t.FromBatch != b.RelayedFrom {
595					return fmt.Errorf("%w: 批次 %q 标记的续接来源（原批次=%q 续接请求号=%q）无法对应",
596						ErrCorrupt, id, b.RelayedFrom, b.RelayRequest)
597				}
598			} else if b.RelayRequest != "" {
599				return fmt.Errorf("%w: 批次 %q 标记了续接请求号 %q 但缺少来源批次", ErrCorrupt, id, b.RelayRequest)
600			}
601		}
602		for req, rc := range l.Receipts {
603			if rc == nil || req != rc.Request || rc.Batch == "" || rc.Parcel == "" || rc.Time.IsZero() ||
604				(rc.Result != resultSigned && rc.Result != resultFailed) ||
605				(rc.Result == resultFailed && rc.Reason == "") || (rc.Result == resultSigned && rc.Reason != "") {
606				return fmt.Errorf("%w: 回执请求号 %q 的回执结果不完整", ErrCorrupt, req)
607			}
608			b, ok := l.Batches[rc.Batch]
609			if !ok {
610				return fmt.Errorf("%w: 回执请求号 %q 引用了不存在的批次 %q", ErrCorrupt, req, rc.Batch)
611			}
612			// 每件包裹的当前回执条目一旦建立只会被新回执取代、不会删除，
613			// 因此该件在批次内必须始终有一条回执条目。
614			e, cur := b.Receipts[rc.Parcel]
615			if !cur {
616				return fmt.Errorf("%w: 回执请求号 %q 在批次 %q 中缺少包裹 %q 的回执条目", ErrCorrupt, req, rc.Batch, rc.Parcel)
617			}
618			if rc.RevokedBy == "" {
619				// 未撤销回执必须仍是该件在该批次的当前有效回执。
620				if e.Request != req || e.Result != rc.Result || e.Reason != rc.Reason || !e.Time.Equal(rc.Time) || e.RevokedBy != "" {
621					return fmt.Errorf("%w: 回执请求号 %q 与批次 %q 的回执记录不一致", ErrCorrupt, req, rc.Batch)
622				}
623				continue
624			}
625			// 已撤销回执：撤销关联必须存在且回指该回执。
626			rv, ok := l.Revokes[rc.RevokedBy]
627			if !ok || rv.Receipt != req {
628				return fmt.Errorf("%w: 回执请求号 %q 标记的撤销请求号 %q 无法对应", ErrCorrupt, req, rc.RevokedBy)
629			}
630			if e.Request == req {
631				// 该件之后未重新回执：批次内条目必须同内容并同样标记撤销。
632				if e.Result != rc.Result || e.Reason != rc.Reason || !e.Time.Equal(rc.Time) || e.RevokedBy != rc.RevokedBy {
633					return fmt.Errorf("%w: 回执请求号 %q 与批次 %q 的回执记录不一致", ErrCorrupt, req, rc.Batch)
634				}
635			}
636			// 该件之后已用新请求号重新回执：当前条目属于新回执，由其自身校验。
637		}
638		// 撤销：每条撤销必须对应一条已撤销回执，批次、包裹一致，且包裹轨迹中有
639		// 与该撤销请求一致的撤销回执记录；撤销关联缺失或不一致即损坏。
640		for req, rv := range l.Revokes {
641			if rv == nil || req != rv.Request || rv.Receipt == "" || rv.Batch == "" || rv.Parcel == "" ||
642				rv.Reason == "" || rv.Time.IsZero() {
643				return fmt.Errorf("%w: 撤销请求号 %q 的撤销结果不完整", ErrCorrupt, req)
644			}
645			rc, ok := l.Receipts[rv.Receipt]
646			if !ok {
647				return fmt.Errorf("%w: 撤销请求号 %q 引用了不存在的原回执 %q", ErrCorrupt, req, rv.Receipt)
648			}
649			if rc.RevokedBy != req {
650				return fmt.Errorf("%w: 撤销请求号 %q 与原回执 %q 的撤销标记不一致", ErrCorrupt, req, rv.Receipt)
651			}
652			if rc.Batch != rv.Batch || rc.Parcel != rv.Parcel {
653				return fmt.Errorf("%w: 撤销请求号 %q 的批次或包裹与原回执 %q 不一致", ErrCorrupt, req, rv.Receipt)
654			}
655			p, ok := l.Parcels[rv.Parcel]
656			if !ok {
657				return fmt.Errorf("%w: 撤销请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, rv.Parcel)
658			}
659			found := false
660			for _, e := range p.Trail {
661				if e.Op == "撤销回执" && e.Request == req {
662					found = true
663					break
664				}
665			}
666			if !found {
667				return fmt.Errorf("%w: 撤销请求号 %q 的包裹 %q 缺少对应的撤销回执轨迹", ErrCorrupt, req, rv.Parcel)
668			}
669		}
670		// 中止：收回集合必须恰为原批次的未回执成员（按原成员顺序，已撤销回执不计入
671		// 有效回执），且每件收回包裹的轨迹中都有与该中止请求一致的收回记录；
672		// 中止记录与收回轨迹不一致即损坏。
673		for req, a := range l.Aborts {
674			if a == nil || req != a.Request || a.Batch == "" || a.Station == "" || a.Reason == "" ||
675				len(a.Parcels) == 0 || a.Time.IsZero() {
676				return fmt.Errorf("%w: 中止请求号 %q 的中止结果不完整", ErrCorrupt, req)
677			}
678			b, ok := l.Batches[a.Batch]
679			if !ok {
680				return fmt.Errorf("%w: 中止请求号 %q 引用了不存在的批次 %q", ErrCorrupt, req, a.Batch)
681			}
682			if b.AbortedBy != req {
683				return fmt.Errorf("%w: 中止请求号 %q 与批次 %q 的中止标记不一致", ErrCorrupt, req, a.Batch)
684			}
685			if a.Station != b.Station {
686				return fmt.Errorf("%w: 中止请求号 %q 的站点 %q 与批次 %q 出发站 %q 不一致", ErrCorrupt, req, a.Station, a.Batch, b.Station)
687			}
688			expect := make([]string, 0, len(b.Parcels))
689			for _, pid := range b.Parcels {
690				if e, done := b.Receipts[pid]; !done || e.RevokedBy != "" {
691					expect = append(expect, pid)
692				}
693			}
694			if len(expect) != len(a.Parcels) {
695				return fmt.Errorf("%w: 中止请求号 %q 的收回集合与批次 %q 的未回执成员不一致", ErrCorrupt, req, a.Batch)
696			}
697			for i := range expect {
698				if expect[i] != a.Parcels[i] {
699					return fmt.Errorf("%w: 中止请求号 %q 的收回集合与批次 %q 的未回执成员不一致", ErrCorrupt, req, a.Batch)
700				}
701			}
702			for _, pid := range a.Parcels {
703				p, ok := l.Parcels[pid]
704				if !ok {
705					return fmt.Errorf("%w: 中止请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, pid)
706				}
707				found := false
708				for _, e := range p.Trail {
709					if e.Op == "收回" && e.Request == req {
710						found = true
711						break
712					}
713				}
714				if !found {
715					return fmt.Errorf("%w: 中止请求号 %q 的收回包裹 %q 缺少对应的收回轨迹", ErrCorrupt, req, pid)
716				}
717			}
718		}
719		// 续接：转交集合必须恰为原批次的未回执成员（按原成员顺序），新批次必须由该续接
720		// 创建且成员、站点、配送员、接手时间与之一致；每件转交包裹的轨迹中都有与该
721		// 续接请求一致的续接记录；续接记录与批次及轨迹不一致即损坏。
722		for req, t := range l.Transfers {
723			if t == nil || req != t.Request || t.FromBatch == "" || t.ToBatch == "" || t.Station == "" ||
724				t.FromCourier == "" || t.ToCourier == "" || t.FromCourier == t.ToCourier ||
725				t.Reason == "" || len(t.Parcels) == 0 || t.Time.IsZero() {
726				return fmt.Errorf("%w: 续接请求号 %q 的续接结果不完整", ErrCorrupt, req)
727			}
728			fb, ok := l.Batches[t.FromBatch]
729			if !ok {
730				return fmt.Errorf("%w: 续接请求号 %q 引用了不存在的原批次 %q", ErrCorrupt, req, t.FromBatch)
731			}
732			if fb.TransferredBy != req {
733				return fmt.Errorf("%w: 续接请求号 %q 与原批次 %q 的转交标记不一致", ErrCorrupt, req, t.FromBatch)
734			}
735			if fb.Station != t.Station || fb.Courier != t.FromCourier {
736				return fmt.Errorf("%w: 续接请求号 %q 的站点或原配送员与原批次 %q 不一致", ErrCorrupt, req, t.FromBatch)
737			}
738			nb, ok := l.Batches[t.ToBatch]
739			if !ok {
740				return fmt.Errorf("%w: 续接请求号 %q 引用了不存在的新批次 %q", ErrCorrupt, req, t.ToBatch)
741			}
742			if nb.RelayedFrom != t.FromBatch || nb.RelayRequest != req {
743				return fmt.Errorf("%w: 续接请求号 %q 与新批次 %q 的来源标记不一致", ErrCorrupt, req, t.ToBatch)
744			}
745			if nb.Station != t.Station || nb.Courier != t.ToCourier || !nb.Time.Equal(t.Time) {
746				return fmt.Errorf("%w: 续接请求号 %q 与新批次 %q 的站点、配送员或接手时间不一致", ErrCorrupt, req, t.ToBatch)
747			}
748			expect := make([]string, 0, len(fb.Parcels))
749			for _, pid := range fb.Parcels {
750				if e, done := fb.Receipts[pid]; !done || e.RevokedBy != "" {
751					expect = append(expect, pid)
752				}
753			}
754			if !sameOrder(expect, t.Parcels) || !sameOrder(t.Parcels, nb.Parcels) {
755				return fmt.Errorf("%w: 续接请求号 %q 的转交集合与原批次 %q 的未回执成员或新批次 %q 的成员不一致",
756					ErrCorrupt, req, t.FromBatch, t.ToBatch)
757			}
758			for _, pid := range t.Parcels {
759				p, ok := l.Parcels[pid]
760				if !ok {
761					return fmt.Errorf("%w: 续接请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, pid)
762				}
763				found := false
764				for _, e := range p.Trail {
765					if e.Op == "续接" && e.Request == req {
766						found = true
767						break
768					}
769				}
770				if !found {
771					return fmt.Errorf("%w: 续接请求号 %q 的转交包裹 %q 缺少对应的续接轨迹", ErrCorrupt, req, pid)
772				}
773			}
774		}
775		// 发运：成员必须非空、不重复且都已登记，每件成员的轨迹中都有与该运输单一致的
776		// 发运记录；未接收运输单的成员必须仍归该单在途（状态为站间在途、归属源站），
777		// 且一件包裹同时只能属于一张未接收运输单；关联缺失或矛盾即损坏。
778		inTransitCount := make(map[string]int) // 包裹 -> 包含它的未接收运输单数
779		for no, sh := range l.Shipments {
780			if sh == nil || no != sh.Shipment || sh.From == "" || sh.To == "" || sh.From == sh.To ||
781				len(sh.Parcels) == 0 || sh.Time.IsZero() {
782				return fmt.Errorf("%w: 运输单号 %q 的发运结果不完整", ErrCorrupt, no)
783			}
784			seen := make(map[string]bool, len(sh.Parcels))
785			for _, pid := range sh.Parcels {
786				if seen[pid] {
787					return fmt.Errorf("%w: 运输单 %q 的成员 %q 重复", ErrCorrupt, no, pid)
788				}
789				seen[pid] = true
790				p, ok := l.Parcels[pid]
791				if !ok {
792					return fmt.Errorf("%w: 运输单 %q 引用了不存在的包裹 %q", ErrCorrupt, no, pid)
793				}
794				found := false
795				for _, e := range p.Trail {
796					if e.Op == "发运" && e.Shipment == no {
797						found = true
798						break
799					}
800				}
801				if !found {
802					return fmt.Errorf("%w: 运输单 %q 的成员包裹 %q 缺少对应的发运轨迹", ErrCorrupt, no, pid)
803				}
804			}
805			if sh.ReceivedBy != "" {
806				r, ok := l.Receives[sh.ReceivedBy]
807				if !ok || r.Shipment != no {
808					return fmt.Errorf("%w: 运输单 %q 标记的接收请求号 %q 无法对应", ErrCorrupt, no, sh.ReceivedBy)
809				}
810				continue
811			}
812			for _, pid := range sh.Parcels {
813				p := l.Parcels[pid]
814				inTransitCount[pid]++
815				if p.Status != statusInTransit || p.Station != sh.From {
816					return fmt.Errorf("%w: 运输单 %q 尚未接收，但成员包裹 %q 当前归属 %q、状态 %q，不在该单在途",
817						ErrCorrupt, no, pid, p.Station, p.Status)
818				}
819			}
820		}
821		for id, p := range l.Parcels {
822			if p.Status == statusInTransit && inTransitCount[id] != 1 {
823				return fmt.Errorf("%w: 包裹 %q 当前为站间在途，但未接收运输单数为 %d，应恰好属于一张未接收运输单",
824					ErrCorrupt, id, inTransitCount[id])
825			}
826		}
827		// 接收：接收站点必须等于运输单目的站，成员必须恰为运输单原成员（按发运保存顺序），
828		// 且每件成员的轨迹中都有与该接收请求一致的接收记录；关联缺失或矛盾即损坏。
829		for req, r := range l.Receives {
830			if r == nil || req != r.Request || r.Shipment == "" || r.Station == "" || len(r.Parcels) == 0 || r.Time.IsZero() {
831				return fmt.Errorf("%w: 接收请求号 %q 的接收结果不完整", ErrCorrupt, req)
832			}
833			sh, ok := l.Shipments[r.Shipment]
834			if !ok {
835				return fmt.Errorf("%w: 接收请求号 %q 引用了不存在的运输单 %q", ErrCorrupt, req, r.Shipment)
836			}
837			if sh.ReceivedBy != req {
838				return fmt.Errorf("%w: 接收请求号 %q 与运输单 %q 的接收标记不一致", ErrCorrupt, req, r.Shipment)
839			}
840			if r.Station != sh.To {
841				return fmt.Errorf("%w: 接收请求号 %q 的接收站点 %q 与运输单 %q 目的站 %q 不一致", ErrCorrupt, req, r.Station, r.Shipment, sh.To)
842			}
843			if !sameOrder(r.Parcels, sh.Parcels) {
844				return fmt.Errorf("%w: 接收请求号 %q 的成员与运输单 %q 的原成员不一致", ErrCorrupt, req, r.Shipment)
845			}
846			for _, pid := range r.Parcels {
847				p, ok := l.Parcels[pid]
848				if !ok {
849					return fmt.Errorf("%w: 接收请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, pid)
850				}
851				found := false
852				for _, e := range p.Trail {
853					if e.Op == "接收" && e.Request == req {
854						found = true
855						break
856					}
857				}
858				if !found {
859					return fmt.Errorf("%w: 接收请求号 %q 的成员包裹 %q 缺少对应的接收轨迹", ErrCorrupt, req, pid)
860				}
861			}
862		}
863		// 冻结/解除冻结：先遍历轨迹核对冻结与解除必须成对出现、顺序正确，
864		// 再核对两张结果表与包裹当前状态的对应关系。
865		openIncident := make(map[string]string) // 包裹 -> 当前未解除的异常单号（由轨迹推导）
866		for id, p := range l.Parcels {
867			var open string
868			for i, e := range p.Trail {
869				switch e.Op {
870				case "冻结":
871					if open != "" {
872						return fmt.Errorf("%w: 包裹 %q 第 %d 条冻结时异常单 %q 尚未解除，一件包裹同时只能有一张未解除异常单",
873							ErrCorrupt, id, i+1, open)
874					}
875					open = e.Incident
876				case "解除冻结":
877					if open != e.Incident {
878						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除的异常单 %q 与当前冻结 %q 不匹配",
879							ErrCorrupt, id, i+1, e.Incident, open)
880					}
881					open = ""
882				}
883			}
884			if p.Status == statusFrozen && open == "" {
885				return fmt.Errorf("%w: 包裹 %q 当前为异常冻结，但轨迹中没有未解除的冻结记录", ErrCorrupt, id)
886			}
887			if p.Status != statusFrozen && open != "" {
888				return fmt.Errorf("%w: 包裹 %q 当前状态为 %q，但异常单 %q 尚未解除", ErrCorrupt, id, p.Status, open)
889			}
890			if open != "" {
891				openIncident[id] = open
892			}
893		}
894		for no, f := range l.Freezes {
895			if f == nil || no != f.Incident || f.Parcel == "" || f.Station == "" || f.Reason == "" || f.Time.IsZero() {
896				return fmt.Errorf("%w: 异常单号 %q 的冻结结果不完整", ErrCorrupt, no)
897			}
898			p, ok := l.Parcels[f.Parcel]
899			if !ok {
900				return fmt.Errorf("%w: 异常单 %q 引用了不存在的包裹 %q", ErrCorrupt, no, f.Parcel)
901			}
902			if f.ReleasedBy == "" && p.Station != f.Station {
903				return fmt.Errorf("%w: 异常单 %q 记录的站点 %q 与包裹 %q 当前站点 %q 不一致",
904					ErrCorrupt, no, f.Station, f.Parcel, p.Station)
905			}
906			if f.ReleasedBy != "" {
907				u, ok := l.Unfreezes[f.ReleasedBy]
908				if !ok || u.Incident != no || u.Parcel != f.Parcel {
909					return fmt.Errorf("%w: 异常单 %q 标记的解除请求号 %q 无法对应", ErrCorrupt, no, f.ReleasedBy)
910				}
911			}
912		}
913		activeByParcel := make(map[string]string)
914		for req, u := range l.Unfreezes {
915			if u == nil || req != u.Request || u.Incident == "" || u.Parcel == "" || u.Note == "" || u.Time.IsZero() {
916				return fmt.Errorf("%w: 解除请求号 %q 的解除结果不完整", ErrCorrupt, req)
917			}
918			f, ok := l.Freezes[u.Incident]
919			if !ok {
920				return fmt.Errorf("%w: 解除请求号 %q 引用了不存在的异常单 %q", ErrCorrupt, req, u.Incident)
921			}
922			if f.Parcel != u.Parcel {
923				return fmt.Errorf("%w: 解除请求号 %q 与异常单 %q 对应的包裹不一致", ErrCorrupt, req, u.Incident)
924			}
925			if f.ReleasedBy != req {
926				return fmt.Errorf("%w: 解除请求号 %q 与异常单 %q 的解除标记不一致", ErrCorrupt, req, u.Incident)
927			}
928		}
929		for no, f := range l.Freezes {
930			if f.ReleasedBy != "" {
931				continue
932			}
933			if other, dup := activeByParcel[f.Parcel]; dup {
934				return fmt.Errorf("%w: 包裹 %q 同时存在两张未解除异常单 %q 与 %q", ErrCorrupt, f.Parcel, other, no)
935			}
936			activeByParcel[f.Parcel] = no
937			if openIncident[f.Parcel] != no {
938				return fmt.Errorf("%w: 包裹 %q 当前冻结对应的异常单应为 %q，与未解除异常单 %q 不匹配",
939					ErrCorrupt, f.Parcel, openIncident[f.Parcel], no)
940			}
941			if p := l.Parcels[f.Parcel]; p.Status != statusFrozen {
942				return fmt.Errorf("%w: 异常单 %q 未解除，但包裹 %q 当前状态为 %q", ErrCorrupt, no, f.Parcel, p.Status)
943			}
944		}
945		return nil
946	}
