1022	// Query 返回一件包裹的当前归属、状态和完整轨迹；不存在时返回 ErrNotFound。
1023	func (s *Store) Query(id string) (*Parcel, error) {
1024		p, ok := s.data.Parcels[id]
1025		if !ok {
1026			return nil, fmt.Errorf("%w: %q", ErrNotFound, id)
1027		}
1028		return p, nil
1029	}
