1031	// ActiveFreeze 返回一件包裹当前未解除异常单的冻结结果；包裹不存在或当前未冻结时返回 nil。
1032	func (s *Store) ActiveFreeze(id string) *FreezeResult {
1033		p, ok := s.data.Parcels[id]
1034		if !ok {
1035			return nil
1036		}
1037		if no := activeFreeze(p); no != "" {
1038			return s.data.Freezes[no]
1039		}
1040		return nil
1041	}
