1116	// Return 按原交接整批退回：实物送回该交接的源站点，批次与站点取自原交接结果。
1117	//
1118	// 首次退回：原交接必须存在且尚未成功退回；批次中每件包裹必须仍归属原交接目的站、
1119	// 状态为在站，且最后一条流转记录就是该原交接（请求重放不产生新流转，不影响判定）。
1120	// 任一条件不满足则整批拒绝，不作任何改动。全部满足时整批改归原交接源站（仍为在站），
1121	// 每件按批次顺序追加一条退回记录，原收件、交接轨迹保留不变。
1122	// 相同退回请求号且原交接、原因相同：直接返回首次结果，replayed 为 true，
1123	// 即使包裹之后又被交接也不重新检查；请求号相同但原交接或原因不同：报冲突。
1124	// 退回请求号与交接请求号分属独立去重范围，互不影响；失败的首次退回不占用请求号。
1125	func (s *Store) Return(request, handoffReq, reason string, now time.Time) (result *ReturnResult, replayed bool, err error) {
1126		if saved, ok := s.data.Returns[request]; ok {
1127			if saved.Handoff == handoffReq && saved.Reason == reason {
1128				return saved, true, nil
1129			}
1130			return nil, false, fmt.Errorf("退回请求号 %q 已用于一次不同的退回（原交接=%q 原因=%q），内容冲突",
1131				request, saved.Handoff, saved.Reason)
1132		}
1133	
1134		h, ok := s.data.Handoffs[handoffReq]
1135		if !ok {
1136			return nil, false, fmt.Errorf("退回失败：原交接请求号 %q 不存在", handoffReq)
1137		}
1138		if h.ReturnedBy != "" {
1139			return nil, false, fmt.Errorf("退回失败：原交接 %q 已成功退回（退回请求号 %q），不能再次退回", handoffReq, h.ReturnedBy)
1140		}
1141	
1142		// 先做全部校验，任何一件不满足都整批拒绝。
1143		for _, id := range h.Parcels {
1144			p, ok := s.data.Parcels[id]
1145			if !ok {
1146				return nil, false, fmt.Errorf("退回失败：包裹 %q 未登记，整批退回未执行", id)
1147			}
1148			if inc := activeFreeze(p); inc != "" {
1149				return nil, false, fmt.Errorf("退回失败：包裹 %q 已被异常单 %q 冻结，冻结期间整批退回拒绝，整批退回未执行", id, inc)
1150			}
1151			if p.Station != h.To || p.Status != statusInStation {
1152				return nil, false, fmt.Errorf("退回失败：包裹 %q 当前归属 %q、状态 %q，不在原交接目的站 %q 在站，整批退回未执行",
1153					id, p.Station, p.Status, h.To)
1154			}
1155			last := lastFlowEvent(p.Trail)
1156			if last.Op != "交接" || last.Request != handoffReq {
1157				return nil, false, fmt.Errorf("退回失败：包裹 %q 在原交接 %q 之后又有新的流转，不能退回该交接，整批退回未执行",
1158					id, handoffReq)
1159			}
1160		}
1161	
1162		res := &ReturnResult{
1163			Request: request,
1164			Handoff: handoffReq,
1165			From:    h.To,
1166			To:      h.From,
1167			Reason:  reason,
1168			Parcels: append([]string(nil), h.Parcels...),
1169			Time:    now,
1170		}
1171		s.data.Returns[request] = res
1172		h.ReturnedBy = request
1173	
1174		// 记录旧值，落盘失败时整体回滚。
1175		prev := make(map[string]struct {
1176			station string
1177			trail   []Event
1178		}, len(h.Parcels))
1179		for _, id := range h.Parcels {
1180			p := s.data.Parcels[id]
1181			prev[id] = struct {
1182				station string
1183				trail   []Event
1184			}{p.Station, append([]Event(nil), p.Trail...)}
1185			p.Station = h.From
1186			p.Status = statusInStation
1187			p.Trail = append(p.Trail, Event{
1188				Op:         "退回",
1189				Station:    h.From,
1190				From:       h.To,
1191				Request:    request,
1192				RefRequest: handoffReq,
1193				Reason:     reason,
1194				Time:       now,
1195			})
1196		}
1197	
1198		if err := s.save(); err != nil {
1199			delete(s.data.Returns, request)
1200			h.ReturnedBy = ""
1201			for id, old := range prev {
1202				p := s.data.Parcels[id]
1203				p.Station = old.station
1204				p.Trail = old.trail
1205			}
1206			return nil, false, err
1207		}
1208		return res, false, nil
1209	}
