1290	// Receipt 提交一件包裹在某个配送批次下的回执。
1291	//
1292	// 首次回执：批次必须存在，包裹必须属于该批次、在该批次没有未撤销的回执，且当前仍在该批次
1293	// 配送中；任一不满足则拒绝，不作任何改动。签收后状态为“已签收”；失败表示实物已回到
1294	// 出发站，恢复“在站”，可加入新的配送批次。两种结果都保留站点并追加一条含批次、结果、
1295	// 原因（失败时）、请求号和时间的回执记录；全部成员均有未撤销回执后批次自动完成。
1296	// 已撤销的回执不再占用该件的回执名额，可用新请求号重新回执（见 RevokeReceipt）。
1297	// 相同回执请求号且批次、包裹、结果、清理后的原因相同：直接返回首次结果，replayed 为
1298	// true，不重新检查当前状态，即使失败包裹已进入新批次或该回执已被撤销（重放不恢复回执，
1299	// 结果中可辨认已撤销）；请求号相同但内容不同报冲突。
1300	// 回执请求号与批次号、包裹编号、交接及退回请求号分属独立去重范围，允许同名；
1301	// 失败的首次回执不占用请求号。
1302	func (s *Store) Receipt(request, batch, parcel, result, reason string, now time.Time) (res *ReceiptResult, replayed bool, err error) {
1303		res, replayed, undo, err := s.applyReceipt(request, batch, parcel, result, reason, now)
1304		if err != nil || replayed {
1305			return res, replayed, err
1306		}
1307		if err := s.save(); err != nil {
1308			undo() // 落盘失败：回滚内存变更，保留原有有效数据
1309			return nil, false, err
1310		}
1311		return res, false, nil
1312	}
1313	
1314	// applyReceipt 在内存台账上校验并应用一条回执（不落盘），是 Receipt 与
1315	// ImportReceipts 共用的核心。全部校验通过后才会改动数据；返回的 undo 可在
1316	// 整体保存失败时撤销本次改动（重放或校验失败时 undo 为 nil）。
1317	func (s *Store) applyReceipt(request, batch, parcel, result, reason string, now time.Time) (res *ReceiptResult, replayed bool, undo func(), err error) {
1318		if saved, ok := s.data.Receipts[request]; ok {
1319			if saved.Batch == batch && saved.Parcel == parcel && saved.Result == result && saved.Reason == reason {
1320				return saved, true, nil, nil
1321			}
1322			return nil, false, nil, fmt.Errorf("回执请求号 %q 已用于一次不同的回执（批次=%q 包裹=%q 结果=%q），内容冲突",
1323				request, saved.Batch, saved.Parcel, saved.Result)
1324		}
1325	
1326		b, ok := s.data.Batches[batch]
1327		if !ok {
1328			return nil, false, nil, fmt.Errorf("回执失败：批次号 %q 不存在", batch)
1329		}
1330		member := false
1331		for _, id := range b.Parcels {
1332			if id == parcel {
1333				member = true
1334				break
1335			}
1336		}
1337		if !member {
1338			return nil, false, nil, fmt.Errorf("回执失败：包裹 %q 不属于批次 %q", parcel, batch)
1339		}
1340		if e, done := b.Receipts[parcel]; done && e.RevokedBy == "" {
1341			return nil, false, nil, fmt.Errorf("回执失败：包裹 %q 在批次 %q 中已回执，每件在一个批次只能有一条未撤销回执", parcel, batch)
1342		}
1343		p := s.data.Parcels[parcel] // 批次成员必已登记（载入校验保证）
1344		if p.Status != statusDelivering || currentBatch(p) != batch {
1345			return nil, false, nil, fmt.Errorf("回执失败：包裹 %q 当前状态为 %q，不在批次 %q 配送中", parcel, p.Status, batch)
1346		}
1347	
1348		res = &ReceiptResult{
1349			Request: request,
1350			Batch:   batch,
1351			Parcel:  parcel,
1352			Result:  result,
1353			Reason:  reason,
1354			Time:    now,
1355		}
1356		entry := &ReceiptEntry{Request: request, Result: result, Reason: reason, Time: now}
1357	
1358		// 记录旧值，undo 在整体落盘失败时回滚。
1359		oldStatus, oldStation := p.Status, p.Station
1360		oldTrailLen := len(p.Trail)
1361		oldEntry, hadEntry := b.Receipts[parcel] // 被取代的已撤销条目（若有）
1362	
1363		if result == resultSigned {
1364			p.Status = statusSigned // 站点保留不变
1365		} else {
1366			p.Status = statusInStation // 实物已回到出发站，可加入新的配送批次
1367			p.Station = b.Station
1368		}
1369		p.Trail = append(p.Trail, Event{
1370			Op:      "回执",
1371			Station: p.Station,
1372			Batch:   batch,
1373			Result:  result,
1374			Reason:  reason,
1375			Request: request,
1376			Time:    now,
1377		})
1378		b.Receipts[parcel] = entry
1379		s.data.Receipts[request] = res
1380	
1381		undo = func() {
1382			delete(s.data.Receipts, request)
1383			if hadEntry {
1384				b.Receipts[parcel] = oldEntry
1385			} else {
1386				delete(b.Receipts, parcel)
1387			}
1388			p.Status, p.Station = oldStatus, oldStation
1389			p.Trail = p.Trail[:oldTrailLen]
1390		}
1391		return res, false, undo, nil
1392	}
