2064				return nil, false, fmt.Errorf("接收失败：包裹 %q 当前归属 %q、状态 %q，不在运输单 %q 从源站 %q 在途，整单接收未执行",
2065					pid, p.Station, p.Status, shipment, sh.From)
2066			}
2067		}
2068	
2069		res = &ReceiveResult{
2070			Request:  request,
2071			Shipment: shipment,
2072			Station:  station,
2073			Parcels:  append([]string(nil), sh.Parcels...),
2074			Time:     now,
2075		}
2076		s.data.Receives[request] = res
2077		sh.ReceivedBy = request
2078	
2079		// 记录旧值，落盘失败时整体回滚。
2080		prev := make(map[string]struct {
2081			station string
2082			status  string
2083			trail   []Event
2084		}, len(sh.Parcels))
2085		for _, pid := range sh.Parcels {
2086			p := s.data.Parcels[pid]
2087			prev[pid] = struct {
2088				station string
2089				status  string
2090				trail   []Event
2091			}{p.Station, p.Status, append([]Event(nil), p.Trail...)}
2092			p.Station = sh.To
2093			p.Status = statusInStation
2094			p.Trail = append(p.Trail, Event{
2095				Op:       "接收",
2096				Station:  sh.To,
2097				From:     sh.From,
2098				To:       sh.To,
2099				Shipment: shipment,
2100				Request:  request,
2101				Time:     now,
2102			})
2103		}
2104	
2105		if err := s.save(); err != nil {
2106			delete(s.data.Receives, request)
2107			sh.ReceivedBy = ""
2108			for pid, old := range prev {
2109				p := s.data.Parcels[pid]
2110				p.Station, p.Status = old.station, old.status
2111				p.Trail = old.trail
2112			}
2113			return nil, false, err
2114		}
2115		return res, false, nil
2116	}
2117	
2118	// ShipmentQuery 按运输单号返回发运结果；运输单不存在时报错。
2119	func (s *Store) ShipmentQuery(shipment string) (*ShipmentResult, error) {
2120		sh, ok := s.data.Shipments[shipment]
2121		if !ok {
2122			return nil, fmt.Errorf("运输单 %q 不存在", shipment)
2123		}
2124		return sh, nil
2125	}
2126	
2127	// ReceiveOf 按接收请求号返回接收结果；不存在时返回 nil。
2128	func (s *Store) ReceiveOf(request string) *ReceiveResult {
2129		return s.data.Receives[request]
2130	}
2131	
2132	// ActiveShipment 返回包裹当前所属的未接收运输单；包裹不存在或不在站间在途时返回 nil。
2133	func (s *Store) ActiveShipment(id string) *ShipmentResult {
2134		p, ok := s.data.Parcels[id]
2135		if !ok || p.Status != statusInTransit {
2136			return nil
2137		}
2138		for _, sh := range s.data.Shipments {
2139			if sh.ReceivedBy != "" {
2140				continue
2141			}
2142			for _, pid := range sh.Parcels {
2143				if pid == id {
2144					return sh
2145				}
2146			}
2147		}
2148		return nil
2149	}
2150	
2151	// currentBatch 返回包裹当前配送归属的批次号（最后一条出站或续接记录的批次）；
2152	// 不在配送中返回空。续接不新增出站记录，但会把当前配送归属切换到新批次。
2153	func currentBatch(p *Parcel) string {
2154		for i := len(p.Trail) - 1; i >= 0; i-- {
2155			if p.Trail[i].Op == "出站" || p.Trail[i].Op == "续接" {
2156				return p.Trail[i].Batch
2157			}
2158		}
2159		return ""
2160	}
2161	
2162	// activeFreeze 返回包裹当前未解除冻结对应的异常单号；未冻结返回空。
2163	// 冻结状态与轨迹成对追加，故当前状态为异常冻结时最后一条冻结记录即为当前异常单。
2164	func activeFreeze(p *Parcel) string {
2165		if p.Status != statusFrozen {
2166			return ""
2167		}
2168		for i := len(p.Trail) - 1; i >= 0; i-- {
2169			if p.Trail[i].Op == "冻结" {
2170				return p.Trail[i].Incident
2171			}
2172		}
2173		return ""
2174	}
2175	
2176	// lastFlowEvent 返回轨迹中最后一条真实流转记录（交接/退回/出站/回执/收回/续接/撤销回执/发运/接收）。
2177	// 冻结与解除只是管理记录，不算新流转，判定旧交接可否退回时须跳过它们。
2178	func lastFlowEvent(trail []Event) Event {
2179		for i := len(trail) - 1; i >= 0; i-- {
2180			switch trail[i].Op {
2181			case "冻结", "解除冻结":
2182				continue
2183			default:
2184				return trail[i]
2185			}
2186		}
2187		return Event{}
2188	}
2189	
2190	// BatchQuery 返回一个配送批次的出站结果与逐件回执进度；批次不存在时报错。
2191	func (s *Store) BatchQuery(batch string) (*BatchResult, error) {
2192		b, ok := s.data.Batches[batch]
2193		if !ok {
2194			return nil, fmt.Errorf("批次 %q 不存在", batch)
2195		}
2196		return b, nil
2197	}
2198	
2199	// sameOrder 判断两个列表长度与逐元素顺序完全一致。
2200	func sameOrder(a, b []string) bool {
2201		if len(a) != len(b) {
2202			return false
2203		}
2204		for i := range a {
2205			if a[i] != b[i] {
2206				return false
2207			}
2208		}
2209		return true
2210	}
2211	
2212	// sameSet 判断两个包裹列表作为集合是否相同（顺序不影响判定）。
2213	func sameSet(a, b []string) bool {
2214		if len(a) != len(b) {
2215			return false
2216		}
2217		x := append([]string(nil), a...)
2218		y := append([]string(nil), b...)
2219		sort.Strings(x)
2220		sort.Strings(y)
2221		for i := range x {
2222			if x[i] != y[i] {
2223				return false
2224			}
2225		}
2226		return true
2227	}
2228	
2229	// save 将当前台账作为一个整体原子写入数据文件：先写临时文件并同步，
2230	// 校验可重新解析后再原子替换，最后目录同步，避免保存失败留下部分业务变更。
2231	func (s *Store) save() error {
2232		if err := os.MkdirAll(filepath.Dir(s.path), 0o755); err != nil {
2233			return fmt.Errorf("保存数据文件失败: %w", err)
2234		}
2235		buf, err := json.MarshalIndent(s.data, "", "  ")
2236		if err != nil {
2237			return fmt.Errorf("保存数据文件失败: %w", err)
2238		}
2239		buf = append(buf, '\n')
2240	
2241		tmp, err := os.CreateTemp(filepath.Dir(s.path), ".parcelhub-*.tmp")
2242		if err != nil {
2243			return fmt.Errorf("保存数据文件失败: %w", err)
2244		}
2245		tmpName := tmp.Name()
2246		cleanup := func() { _ = os.Remove(tmpName) }
2247	
2248		if _, err := tmp.Write(buf); err != nil {
2249			_ = tmp.Close()
2250			cleanup()
2251			return fmt.Errorf("保存数据文件失败: %w", err)
2252		}
2253		if err := tmp.Sync(); err != nil {
2254			_ = tmp.Close()
2255			cleanup()
2256			return fmt.Errorf("保存数据文件失败: %w", err)
2257		}
2258		if err := tmp.Close(); err != nil {
2259			cleanup()
2260			return fmt.Errorf("保存数据文件失败: %w", err)
2261		}
2262	
2263		// 替换前确认临时文件自身可解析，杜绝把损坏内容写到正式位置。
2264		var check ledgerFile
2265		if err := json.Unmarshal(buf, &check); err != nil {
2266			cleanup()
2267			return fmt.Errorf("保存数据文件失败: 写入内容无效: %w", err)
2268		}
2269	
2270		if err := os.Rename(tmpName, s.path); err != nil {
2271			cleanup()
2272			return fmt.Errorf("保存数据文件失败: %w", err)
2273		}
2274		if dir, err := os.Open(filepath.Dir(s.path)); err == nil {
2275			_ = dir.Sync()
2276			_ = dir.Close()
2277		}
2278		return nil
2279	}
