// 运输生命周期：按每件包裹轨迹的保存顺序（不按时间）核对发运与接收的配对。
// 每张运输单的成员恰有一次对应发运；已接收时恰有一次对应接收且位于发运之后；
// 发运后到接收前不得出现其他作业轨迹；未接收时发运必须是最后一条轨迹；
// 接收后没有后续作业时，成员必须在目的站在站。
for id, p := range l.Parcels {
    shipped := make(map[string]bool)   // 该包裹出现过的发运运输单号
    receivedReq := make(map[string]bool) // 该包裹出现过的接收请求号
    var open string                    // 当前未接收的发运运输单号（按轨迹顺序推导）
    var openIdx int
    for i, e := range p.Trail {
        switch e.Op {
        case "发运":
            if open != "" {
                return fmt.Errorf("%w: 包裹 %q 第 %d 条发运时运输单 %q 尚未接收，发运后到接收前不得出现其他作业轨迹", ErrCorrupt, id, i+1, open)
            }
            if shipped[e.Shipment] {
                return fmt.Errorf("%w: 包裹 %q 第 %d 条发运与运输单 %q 的首次发运重复，每张运输单的成员恰有一次对应发运", ErrCorrupt, id, i+1, e.Shipment)
            }
            shipped[e.Shipment] = true
            open = e.Shipment
            openIdx = i
        case "接收":
            if open == "" {
                return fmt.Errorf("%w: 包裹 %q 第 %d 条接收之前没有对应的发运轨迹", ErrCorrupt, id, i+1)
            }
            if open != e.Shipment {
                return fmt.Errorf("%w: 包裹 %q 第 %d 条接收的运输单 %q 与当前在途运输单 %q 不一致", ErrCorrupt, id, i+1, e.Shipment, open)
            }
            if receivedReq[e.Request] {
                return fmt.Errorf("%w: 包裹 %q 第 %d 条接收与接收请求 %q 的首次接收重复", ErrCorrupt, id, i+1, e.Request)
            }
            receivedReq[e.Request] = true
            open = ""
        default:
            if open != "" {
                return fmt.Errorf("%w: 包裹 %q 第 %d 条轨迹（%s）出现在运输单 %q 发运之后、接收之前，在途期间不得有其他作业轨迹", ErrCorrupt, id, i+1, e.Op, open)
            }
        }
    }
    if open != "" {
        sh := l.Shipments[open] // 发运轨迹校验已保证存在
        if sh.ReceivedBy != "" {
            return fmt.Errorf("%w: 运输单 %q 已接收（接收请求号 %q），但成员包裹 %q 缺少对应的接收轨迹", ErrCorrupt, open, sh.ReceivedBy, id)
        }
        // 未接收：发运必须是最后一条轨迹（遍历已保证其后没有任何其他轨迹）。
        _ = openIdx
    }
    // 接收后没有后续作业时，成员必须在目的站在站。
    if last := p.Trail[len(p.Trail)-1]; last.Op == "接收" {
        if p.Station != last.To || p.Status != statusInStation {
            return fmt.Errorf("%w: 包裹 %q 最后一条轨迹为运输单 %q 的接收，但当前归属 %q、状态 %q，不在目的站 %q 在站",
                ErrCorrupt, id, last.Shipment, p.Station, p.Status, last.To)
        }
    }
}
