210			t.Fatalf("运输单应永久标记已接收: %+v err=%v", sh, err)
211		}
212		// 按原顺序全部改归目的站、恢复在站，各追加接收轨迹。
213		for _, id := range []string{"P001", "P002"} {
214			p, _ := s.Query(id)
