216				t.Fatalf("接收后包裹 %q 应归目的站在站: status=%q station=%q", id, p.Status, p.Station)
217			}
218			last := p.Trail[len(p.Trail)-1]
219			if last.Op != "接收" || last.Shipment != "S1" || last.Request != "RS1" ||
220				last.From != "站点A" || last.To != "站点B" || !last.Time.Equal(recvTime) {
221				t.Fatalf("包裹 %q 缺少接收轨迹: %+v", id, last)
222			}
223			if sh := s.ActiveShipment(id); sh != nil {
224				t.Fatalf("接收后包裹 %q 不应再属于未接收运输单", id)
225			}
226		}
227		// 接收后可继续在站作业。
228		mustHandoff(t, s, "R9", "站点B", "站点C", []string{"P001"}, tClock(2026, 10, 5, 13, 0))
229	}
