248		if p1.Station != "站点C" {
249			t.Fatalf("重放不应改变后续流转结果: %+v", p1)
250		}
251		p2, _ := s.Query("P002")
252		if len(p2.Trail) != 3 {
253			t.Fatalf("重放不应追加轨迹，得到 %d 条", len(p2.Trail))
254		}
255	
256		// 换内容冲突：换运输单或换接收站点均拒绝。
257		mustShip(t, s, "S2", "站点B", "站点C", []string{"P002"}, tClock(2026, 10, 5, 14, 30))
258		if _, _, err := s.Receive("RS1", "S2", "站点C", tClock(2026, 10, 5, 15, 0)); err == nil ||
259			!strings.Contains(err.Error(), "冲突") {
260			t.Fatalf("换运输单应报冲突: %v", err)
261		}
262		if _, _, err := s.Receive("RS1", "S1", "站点C", tClock(2026, 10, 5, 15, 0)); err == nil ||
263			!strings.Contains(err.Error(), "冲突") {
264			t.Fatalf("换接收站点应报冲突: %v", err)
265		}
266	
267		// 换请求号再次接收同一运输单拒绝。
268		if _, _, err := s.Receive("RS2", "S1", "站点B", tClock(2026, 10, 5, 15, 0)); err == nil {
269			t.Fatalf("换请求号再次接收同一运输单应拒绝")
270		}
271	
272		// 接收请求号与运输单号及其他编号独立，可同名。
273		mustReceive(t, s, "S2", "S2", "站点C", tClock(2026, 10, 5, 16, 0))
274	}
