355	// 新增记录的关联为空、缺失或与包裹、轨迹矛盾时明确拒绝读写，不崩溃或覆盖。
356	func TestShipReceiveCorrupt(t *testing.T) {
357		s, path := openTempStore(t)
358		setupShipBase(t, s)
359		mustShip(t, s, "S1", "站点A", "站点B", []string{"P001"}, tClock(2026, 10, 5, 10, 0))
360		mustReceive(t, s, "RS1", "S1", "站点B", tClock(2026, 10, 5, 12, 0))
361	
362		raw, err := os.ReadFile(path)
363		if err != nil {
364			t.Fatalf("读取数据文件失败: %v", err)
365		}
366		mutate := func(name string, fn func(m map[string]any)) {
367			t.Helper()
368			var m map[string]any
369			if err := json.Unmarshal(raw, &m); err != nil {
370				t.Fatalf("解析数据文件失败: %v", err)
371			}
372			fn(m)
373			buf, err := json.Marshal(m)
374			if err != nil {
375				t.Fatalf("编码失败: %v", err)
376			}
377			if err := os.WriteFile(path, buf, 0o644); err != nil {
378				t.Fatal(err)
379			}
380			if _, err := Open(path); !errors.Is(err, ErrCorrupt) {
381				t.Fatalf("%s：应拒绝读写，得到 err=%v", name, err)
382			}
383		}
384		shipment := func(m map[string]any) map[string]any { return m["shipments"].(map[string]any)["S1"].(map[string]any) }
385		receive := func(m map[string]any) map[string]any { return m["receives"].(map[string]any)["RS1"].(map[string]any) }
386		parcel := func(m map[string]any) map[string]any { return m["parcels"].(map[string]any)["P001"].(map[string]any) }
387	
388		mutate("运输单结果缺失", func(m map[string]any) { delete(m, "shipments") })
389		mutate("接收结果缺失", func(m map[string]any) { delete(m, "receives") })
390		mutate("运输单缺少目的站", func(m map[string]any) { shipment(m)["to"] = "" })
391		mutate("运输单引用不存在的包裹", func(m map[string]any) { shipment(m)["parcels"] = []any{"P404"} })
392		mutate("接收请求引用不存在的运输单", func(m map[string]any) { receive(m)["shipment"] = "S404" })
393		mutate("接收站点与目的站矛盾", func(m map[string]any) { receive(m)["station"] = "站点C" })
394		mutate("运输单接收标记缺失", func(m map[string]any) { delete(shipment(m), "receivedBy") })
395		mutate("接收成员与运输单矛盾", func(m map[string]any) { receive(m)["parcels"] = []any{"P002"} })
396		mutate("包裹缺少接收轨迹", func(m map[string]any) {
397			trail := parcel(m)["trail"].([]any)
398			parcel(m)["trail"] = trail[:len(trail)-1]
399		})
400		mutate("在途状态与运输单矛盾", func(m map[string]any) {
401			// 去掉接收结果与接收轨迹，但包裹状态仍是在站而非站间在途。
402			delete(m, "receives")
403			delete(shipment(m), "receivedBy")
404			trail := parcel(m)["trail"].([]any)
405			parcel(m)["trail"] = trail[:len(trail)-1]
406		})
407	
408		// 篡改不留下有效文件：还原后旧有效台账直接使用。
409		if err := os.WriteFile(path, raw, 0o644); err != nil {
410			t.Fatal(err)
411		}
412		if _, err := Open(path); err != nil {
413			t.Fatalf("还原后应能正常打开: %v", err)
414		}
415	}
